import java.io.BufferedOutputStream;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringTokenizer;

public class EducationalRound86E {

    static long mod = 998244353L;
    static int max = (int)4e5 + 10;
    static long[] fact;
    static long[] invFact;

    static void precompute() {
        fact = new long[max];
        invFact = new long[max];
        fact[0] = fact[1] = invFact[0] = invFact[1] = 1L;
        for (int i = 2; i < max; i++) {
            fact[i] = (fact[i - 1] * (long)i) % mod;
            invFact[i] = (invFact[i - 1] * modInv(i, mod)) % mod;
        }
    }

    static long nCr(int n, int r) {
        long res = fact[n] * invFact[r] % mod;
        res = res * invFact[n - r] % mod;
        return res;
    }

    static long powMod(long a, long n) {
        if (n == 0) return 1L;
        long half = powMod(a, n / 2);
        half = half * half % mod;
        if ((n & 1) == 1) half = half * a % mod;
        return half;
    }

    static void solve() {
        precompute();
        int n = sc.nextInt();
        long k = sc.nextLong();
        if (k == 0) {
            out.println(fact[n]);
            return;
        }
        if (n <= k) {
            out.println(0);
            return;
        }
        long comb = nCr(n, (int)k);
        int cols = n - (int)k;
        long sum = 0L;
        for (int i = 0; i <= cols; i++) {
            long term = nCr(cols, i);
            term = term * powMod(cols - i, n) % mod;
            if ((i & 1) == 1) {
                sum -= term;
                if (sum < 0) sum += mod;
            } else {
                sum += term;
                if (sum >= mod) sum -= mod;
            }
        }
        out.println((2L * ((comb * sum) % mod)) % mod);
    }

    public static void main(String[] args) {
        out = new PrintWriter(new BufferedOutputStream(System.out));
        sc = new FastReader();
        solve();
        out.close();
    }

    static class Triplet {
        long gcd;
        long x;
        long y;

        Triplet(long gcd, long x, long y) {
            this.gcd = gcd;
            this.x = x;
            this.y = y;
        }
    }

    static Triplet extendedGcd(long a, long b) {
        if (a == 0) return new Triplet(b, 0, 1);
        Triplet t = extendedGcd(b % a, a);
        long x = t.y - (b / a) * t.x;
        long y = t.x;
        return new Triplet(t.gcd, x, y);
    }

    static long modInv(long a, long m) {
        Triplet t = extendedGcd(a, m);
        if (t.gcd != 1) return -1;
        return (t.x % m + m) % m;
    }

    static FastReader sc;
    static PrintWriter out;

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreTokens()) {
                try {
                    st = new StringTokenizer(br.readLine());
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        double nextDouble() {
            return Double.parseDouble(next());
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        String nextLine() {
            String str = "";
            try {
                str = br.readLine();
            } catch (Exception e) {
                e.printStackTrace();
            }
            return str;
        }
    }
}
